app, err := ridu.New(content.Config(), backend)
if err != nil {
	log.Fatal(err)
}
post, err := app.Local().Find(ctx, "posts", postID, ridu.FindOptions{})

manifest, err := ridu.Resolve(content.Config())
if err != nil {
	log.Fatal(err)
}
fmt.Println(manifest.Snapshot().Version)

err := ridu.Execute(
	content.Config(),
	ridu.WithStore(func(ctx context.Context) (store.Store, error) {
		return postgres.Open(ctx, os.Getenv("DATABASE_URL"))
	}),
	ridu.WithAddress(":8080"),
)
if err != nil {
	log.Fatal(err)
}

var authenticated ridu.AccessRule = func(
	ctx ridu.AccessContext,
) (ridu.AccessDecision, error) {
	if ctx.Actor == nil {
		return ridu.Deny(), nil
	}
	return ridu.Allow(), nil
}

func ownerOnly(ctx ridu.AccessContext) (ridu.AccessDecision, error) {
	if ctx.Actor == nil {
		return ridu.Deny(), nil
	}
	author, err := query.NewPath("author")
	if err != nil {
		return ridu.Deny(), err
	}
	return ridu.Where(
		query.Equal(author, query.String(ctx.Actor.ID)),
	), nil
}

var Posts = ridu.Collection{
	Access: ridu.CollectionAccess{
		Create: authenticated,
		Read:   publishedOrOwner,
		Update: ownerOrEditor,
		Delete: administratorsOnly,
	},
}

var auditTitle ridu.Hook = func(ctx ridu.HookContext) error {
	if ctx.Document == nil {
		return nil
	}
	log.Printf("%s changed %s", ctx.Operation, ctx.Document.ID)
	return nil
}

parameters.description:
BeforeChange runs after initial built-in validation for create, duplicate,
update, publish, and unpublish. Changes to Data are checked again afterward;
custom field validators run after the write hooks finish.

AfterCommit runs after a successful commit, including read transactions.
Guard write-only effects with Operation. It runs outside the transaction;
failures cannot roll back saved data, and later effects still run.

