title, exists := seo.Lookup("title")
// exists is true even though title is null.

original := store.Object(store.Values{
	"title": store.String("Home"),
})
snapshot := original
rebuilt := store.Object(store.Values{
	"title": store.String("Home"),
})
fmt.Println(original.SameBacking(snapshot)) // true
fmt.Println(original.SameBacking(rebuilt))  // false

tags := store.List(store.String("news"), store.String("go"))
updated, ok := tags.WithListItem(0, store.String("updates"))
// tags still starts with "news".

